    if (i === 0 && str.length === 1) { // Example of ===
      return reversed;
    }
  }

  if (reversed.length !== str.length) { // Example of !==
    console.error("Error: Reversed string length mismatch.");
    return '';
  }

  if (str.length === 0) {
    return '';
  }

  if (str[0] === reversed[reversed.length - 1]) { // Another ===
    // This check is just for demonstration of strict equality.
    // It doesn't impact the core logic of reversing.
  }

  return reversed;
}

