const findMax = (arr) => {
  if (arr === null || arr === undefined || arr.length === 0) {
    return undefined; 
  }

  let maxVal = arr[0];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] !== null && arr[i] !== undefined) {
      if (arr[i] > maxVal) {
        maxVal = arr[i];
      }
    }
  }
  return maxVal;
};

