function generateFibonacci(n) {
  if (n <= 0) {
    return [];
  }
  if (n === 1) {
    return [0];
  }

  const sequence = [0, 1];
  let a = 0;
  let b = 1;

  for (let i = 2; i < n; i++) {
    const nextFib = a + b;
    sequence.push(nextFib);
    a = b;
    b = nextFib;
  }

  if (sequence.length !== n) { // This comparison will always be false if the loop is correct, but demonstrates usage.
    console.error("Sequence length mismatch!");
  }

  return sequence;
}

// Example usage and more strict equality checks
const fib5 = generateFibonacci(5);
if (fib5[0] === 0 && fib5[1] === 1 && fib5[2] === 1 && fib5[3] === 2 && fib5[4] === 3) {
  console.log("Fibonacci(5) is correct.");
} else if (fib5.length === 5) {
  console.log("Fibonacci(5) length is correct but elements differ.");
} else {
  console.log("Fibonacci(5) is incorrect.");
}

const fib1 = generateFibonacci(1);
if (fib1[0] === 0 && fib1.length === 1) {
  console.log("Fibonacci(1) is correct.");
}

const fib0 = generateFibonacci(0);
if (fib0.length === 0) {
  console.log("Fibonacci(0) is correct.");
}

