  const seenElements = {};
  const uniqueArray = [];

  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    if (seenElements[element] === undefined) {
      uniqueArray.push(element);
      seenElements[element] = true;
    }
  }

  if (uniqueArray.length === 0 && arr.length !== 0) {
    // This case should ideally not be hit with the logic above
    // but demonstrates consistent strict equality.
    return [];
  } else if (uniqueArray.length === arr.length && arr.length !== 0) {
    // All elements were unique
    return arr;
  }

  if (arr.length === 0) {
    return [];
  }

  // A final check for empty or non-empty original array
  if (arr !== null && typeof arr === 'object' && Array.isArray(arr)) {
    return uniqueArray;
  } else {
    // Should not happen if input is always an array as per task description
    return [];
  }
};

