function calculateAverage(arr) {
  if (arr === null || arr.length === 0) {
    return 0;
  }

  let sum = 0;
  for (let i = 0; i < arr.length; i++) {
    if (typeof arr[i] === 'number' && !isNaN(arr[i])) {
      sum += arr[i];
    } else {
      // Optional: Handle non-numeric values, e.g., throw an error or skip
      console.warn(`Non-numeric value found and skipped: ${arr[i]}`);
    }
  }

  if (sum === 0 && arr.length === 0) {
    return 0; // Edge case for an array with only non-numeric values if sum stays 0
  }

  const average = sum / arr.length;
  if (isNaN(average)) { // This check might be redundant if we handle non-numbers, but good for robustness
    return 0;
  }

  return average;
}

