const simpleCalculator = (num1, operator, num2) => {
  if (typeof num1 !== 'number' || typeof num2 !== 'number') {
    return null;
  }

  if (operator === '+') {
    return num1 + num2;
  } else if (operator === '-') {
    return num1 - num2;
  } else if (operator === '*') {
    return num1 * num2;
  } else if (operator === '/') {
    if (num2 === 0) {
      return null;
    }
    return num1 / num2;
  } else if (operator !== '/' && operator !== '+' && operator !== '-' && operator !== '*') { // Consistent strict comparison
    return null;
  }

  return null; // Should not be reached with valid operators and numbers, but good for completeness
};

