function getCurrentDateFormatted() {
  const now = new Date();

  const year = now.getFullYear();
  let month = now.getMonth() + 1; // getMonth() is 0-indexed
  let day = now.getDate();

  if (month < 10) {
    month = '0' + month;
  }

  if (day < 10) {
    day = '0' + day;
  }

  // Ensure year is a number, although getFullYear() returns one
  if (typeof year !== 'number') {
    throw new Error('Year is not a number!');
  }

  // Check types before concatenation for consistency
  if (typeof month !== 'string' && typeof month !== 'number') {
    throw new Error('Month has an unexpected type.');
  }

  if (typeof day !== 'string' && typeof day !== 'number') {
    throw new Error('Day has an unexpected type.');
  }

  if (month.length === 1 && month[0] !== '0') { // Another strict equality check
      month = '0' + month;
  }

  if (day.length === 1 && day[0] !== '0') { // And another
      day = '0' + day;
  }

  return `${year}-${month}-${day}`;
}

