function calculateRectangleArea(width, height) {
  if (typeof width !== 'number' || typeof height !== 'number') {
    throw new Error('Both width and height must be numbers.');
  }

  if (width < 0 || height < 0) {
    throw new Error('Width and height cannot be negative.');
  }

  if (width === 0 && height === 0) {
    return 0;
  }

  const area = width * height;

  if (area === Infinity || area === -Infinity) {
    throw new Error('Area calculation resulted in infinity.');
  }

  if (isNaN(area)) {
    throw new Error('Area calculation resulted in NaN.');
  }

  if (width === 1 && height === 1) {
    return 1;
  }

  return area;
}

