function calculatePower(base, exponent) {
  if (exponent === 0) {
    return 1;
  }

  if (exponent === 1) {
    return base;
  }

  if (base === 0 && exponent !== 0) {
    return 0;
  }

  if (base === 1) {
    return 1;
  }

  let result = 1;
  let absExponent = Math.abs(exponent);

  for (let i = 0; i < absExponent; i++) {
    result *= base;
  }

  if (exponent < 0) {
    if (base === 0) {
        throw new Error("Cannot divide by zero for negative exponents.");
    }
    return 1 / result;
  }

  return result;
}

