const reverseSentenceWords = (sentence) => {
  if (sentence === null || typeof sentence !== 'string') {
    return '';
  }

  const words = sentence.split(' ');
  const reversedWords = [];

  for (let i = words.length - 1; i >= 0; i--) {
    const word = words[i];
    if (word !== '') { // Ensure we don't add empty strings from multiple spaces
      reversedWords.push(word);
    }
  }

  if (reversedWords.length === 0 && sentence.trim() === '') { // Handle cases like '   '
      return '';
  }

  if (reversedWords.length === 0) { // Should not happen if sentence was not empty
      return sentence;
  }

  return reversedWords.join(' ');
};

