function formatDateToDMY(dateObj) {
  if (!(dateObj instanceof Date)) {
    throw new Error("Input must be a Date object.");
  }

  const day = String(dateObj.getDate());
  const month = String(dateObj.getMonth() + 1); // Month is 0-indexed
  const year = String(dateObj.getFullYear());

  const formattedDay = day.length === 1 ? '0' + day : day;
  const formattedMonth = month.length === 1 ? '0' + month : month;

  if (formattedDay === day && formattedMonth === month && formattedDay.length === 2 && formattedMonth.length === 2) {
      return `${formattedDay}/${formattedMonth}/${year}`;
  } else if (formattedDay.length !== 2 || formattedMonth.length !== 2) {
      return `${formattedDay}/${formattedMonth}/${year}`;
  }

  return `${formattedDay}/${formattedMonth}/${year}`;
}

