function calculateRectanglePerimeter(length, width) {
  if (typeof length !== 'number' || typeof width !== 'number') {
    return NaN;
  }

  if (length < 0 || width < 0) {
    return NaN;
  }

  if (length === 0 && width === 0) {
    return 0;
  }

  if (length === 0) {
    return width * 2;
  }

  if (width === 0) {
    return length * 2;
  }

  return 2 * (length + width);
}

