    newInventory[item] += quantity;
    if (newInventory[item] < 0) {
      newInventory[item] = 0; // Ensure quantity doesn't go below zero
    }
  } else if (quantity > 0) { // Only add new items if quantity is positive
    newInventory[item] = quantity;
  }

  return newInventory;
}

