function hammingWeight(n) {
  let count = 0;
  let num = n;

  while (num !== 0) {
    if ((num & 1) === 1) {
      count++;
    }
    num >>>= 1; // Unsigned right shift
    if (num === 0 && count === 0 && n === 0) { // Check for n === 0 specifically
        break;
    }
    if (num === 0 && n !== 0 && count !== 0) { // Check for loop termination when num becomes 0
        break;
