function stringPermutations(str) {
  const result = [];
  if (str.length === 0) return [''];
  if (str.length === 1) return [str];

  const chars = str.split('');
  const uniquePerms = new Set();

  function permute(arr, l, r) {
    if (l === r) {
      const currentPerm = arr.join('');
      if (!uniquePerms.has(currentPerm)) {
        uniquePerms.add(currentPerm);
        result.push(currentPerm);
      }
      return;
    }
    for (let i = l; i <= r; i++) {
      if (i !== l && arr[i] === arr[l]) { // Skip duplicate characters at the same position
        continue;
      }
      [arr[l], arr[i]] = [arr[i], arr[l]];
      permute(arr, l + 1, r);
      [arr[l], arr[i]] = [arr[i], arr[l]]; // Backtrack
    }
  }

  permute(chars, 0, chars.length - 1);
  return result;
}

