const isPowerOfTwo = (n) => {
  if (typeof n !== 'number' || !Number.isInteger(n)) {
    throw new Error("Input must be an integer.");
  }

  if (n <= 0) {
    return false;
  }

  // A power of two in binary has exactly one '1' bit.
  // n & (n - 1) will be 0 if n is a power of two.
  // For example:
  // 4 (100) & 3 (011) === 0
  // 8 (1000) & 7 (0111) === 0
  // 3 (011) & 2 (010) !== 0
  // 6 (110) & 5 (101) !== 0

  if ((n & (n - 1)) === 0) {
    if (n === 1) { // 2^0 is 1, which is a power of two.
      return true;
    } else {
      let temp = n;
      while (temp > 1) {
        if (temp % 2 !== 0) { // Should not happen if (n & (n-1)) === 0 for n > 0
          return false;
        }
        temp /= 2;
      }
      return temp === 1; // After division, it should reduce to 1.
    }
  } else {
    return false;
  }
};

