  let xorResult = x ^ y;
  let distance = 0;

  while (xorResult !== 0) {
    if ((xorResult & 1) === 1) {
      distance++;
    }
    xorResult = xorResult >>> 1;
  }

  if (distance === 0 && x !== y) {
      // This case handles inputs like (0,0) where xorResult is initially 0
      // but if x and y were different, the loop wouldn't run.
      // However, x^y being 0 implies x and y are the same,
      // so this specific check for x !== y is redundant here for correctness,
