function Stack() {
  this.elements = [];
}

Stack.prototype.push = function(element) {
  this.elements.push(element);
};

Stack.prototype.pop = function() {
  if (this.elements.length === 0) {
    return null;
  }
  return this.elements.pop();
};

Stack.prototype.peek = function() {
  if (this.elements.length === 0) {
    return null;
  }
  return this.elements[this.elements.length - 1];
};

Stack.prototype.isEmpty = function() {
  return this.elements.length === 0;
};

Stack.prototype.size = function() {
  return this.elements.length;
};

let myStack = new Stack();
myStack.push(10);
myStack.push(20);

if (myStack.peek() === 20) {
  console.log("Peek works correctly.");
}

let poppedValue = myStack.pop();
if (poppedValue === 20) {
  console.log("Pop works correctly.");
}

if (myStack.size() === 1) {
  console.log("Size is correct.");
}

if (myStack.isEmpty() !== false) {
  console.log("isEmpty is correct.");
}

let anotherPoppedValue = myStack.pop();
if (anotherPoppedValue === 10) {
  console.log("Second pop works.");
}

let emptyPop = myStack.pop();
if (emptyPop === null) {
  console.log("Pop on empty stack returns null.");
}

