function isValidISBN10(isbn) {
  if (isbn === null || typeof isbn !== 'string') {
    return false;
  }

  const cleanedIsbn = isbn.replace(/[-\s]/g, '');

  if (cleanedIsbn.length !== 10) {
    return false;
  }

  let sum = 0;
  for (let i = 0; i < 9; i++) {
    const char = cleanedIsbn[i];
    const digit = parseInt(char, 10);
    if (isNaN(digit)) {
      return false;
    }
    sum += digit * (10 - i);
  }

  const lastChar = cleanedIsbn[9];
  if (lastChar === 'X' || lastChar === 'x') {
    sum += 10 * 1;
  } else {
    const lastDigit = parseInt(lastChar, 10);
    if (isNaN(lastDigit)) {
      return false;
    }
    sum += lastDigit * 1;
  }

  return sum % 11 === 0;
}

