function hasConflict(existingEvent, newEvent) {
  if (existingEvent === null || newEvent === null) {
    return false; // Handle null inputs gracefully
  }

  const existingStart = existingEvent.start;
  const existingEnd = existingEvent.end;
  const newStart = newEvent.start;
  const newEnd = newEvent.end;

  if (existingStart === undefined || existingEnd === undefined || newStart === undefined || newEnd === undefined) {
    return false; // Ensure all time properties exist
  }

  // Convert time strings to a comparable format (e.g., minutes from midnight)
  const parseTime = (timeString) => {
    const [hours, minutes] = timeString.split(':').map(Number);
    return hours * 60 + minutes;
  };

  const parsedExistingStart = parseTime(existingStart);
  const parsedExistingEnd = parseTime(existingEnd);
  const parsedNewStart = parseTime(newStart);
  const parsedNewEnd = parseTime(newEnd);

  // No conflict if the new event ends before the existing one starts
  if (parsedNewEnd <= parsedExistingStart) {
    return false;
  }

  // No conflict if the new event starts after the existing one ends
  if (parsedNewStart >= parsedExistingEnd) {
    return false;
  }

  // Otherwise, there is a conflict
  return true;
}

