  }

  if (typeof min !== 'number' || typeof max !== 'number') {
    throw new Error("Both min and max must be numbers.");
  }

  if (min > max) {
    [min, max] = [max, min];
  }

  min = Math.ceil(min);
  max = Math.floor(max);

  if (min === max) {
    return min;
  }

  const randomNumber = Math.random();
  const scaledNumber = randomNumber * (max - min + 1);
