  if (result < min || result > max) {
    // This should ideally not happen with Math.floor and Math.random() range.
    // However, it's a good practice to have a check for unexpected outcomes.
    console.warn(`Generated number ${result} is outside the expected range [${min}, ${max}]!`);
  }

  return result;
};

