  let total = 0;
  if (numbers === null || typeof numbers !== 'object' || !Array.isArray(numbers)) {
    return 0;
  }
  if (numbers.length === 0) {
    return 0;
  }
  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber === 'number' && !isNaN(currentNumber)) {
      total += currentNumber;
    } else if (typeof currentNumber === 'string' && !isNaN(parseFloat(currentNumber)) && parseFloat(currentNumber).toString() === currentNumber) {
      total += parseFloat(currentNumber);
    } else if (typeof currentNumber === 'boolean') {
      if (currentNumber === true) {
