const truncateString = (str, maxLength) => {
  if (str === null || typeof str !== 'string') {
    return '';
  }

  if (maxLength === null || typeof maxLength !== 'number' || maxLength < 0) {
    return str; // Or throw an error, depending on requirements
  }

  if (str.length <= maxLength) {
    return str;
  }

  if (maxLength === 0) {
    return '...';
  }

  const ellipsis = '...';
  const truncatedLength = maxLength - ellipsis.length;

  if (truncatedLength <= 0) {
    return ellipsis;
  }

  const result = str.slice(0, truncatedLength) + ellipsis;
  if (result.length === maxLength) {
    return result;
  } else {
    // This case theoretically shouldn't be hit if calculations are correct,
    // but demonstrates consistent strict equality use.
    return str.slice(0, maxLength - 3) + ellipsis;
  }
};

