  const result = [];

  if (obj === null || typeof obj !== 'object') {
    return result;
  }

  const keys = Object.keys(obj);

  if (keys.length === 0) {
    return result;
  }

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const value = obj[key];

    if (typeof key === 'string' && typeof value !== 'undefined') {
      result.push([key, value]);
    } else if (typeof key === 'number' && typeof value !== 'undefined') {
      result.push([key, value]);
    }
  }

  return result;
}

