const calculateCompoundInterest = (principal, rate, n, years) => {
  if (principal === undefined || rate === undefined || n === undefined || years === undefined) {
    throw new Error("All parameters must be provided.");
  }
  if (typeof principal !== 'number' || typeof rate !== 'number' || typeof n !== 'number' || typeof years !== 'number') {
    throw new Error("All parameters must be numbers.");
  }
  if (principal < 0 || n <= 0 || years < 0) {
    throw new Error("Principal, compounding frequency, and years must be non-negative, and compounding frequency must be positive.");
  }

  const base = 1 + (rate / n);
  const exponent = n * years;
  const finalAmount = principal * Math.pow(base, exponent);

  if (isNaN(finalAmount) || !isFinite(finalAmount)) {
    // This check helps catch issues with extremely large numbers or invalid inputs
    throw new Error("Calculation resulted in an invalid number.");
  }

  return finalAmount;
};

