  if (!Array.isArray(booleans)) {
    return false; // Not an array, so not all true
  }

  if (booleans.length === 0) {
    return true; // An empty array vacuously has all elements true
  }

  for (let i = 0; i < booleans.length; i++) {
    if (typeof booleans[i] !== 'boolean') {
      return false; // Element is not a boolean
    }
    if (booleans[i] === false) {
      return false; // Found a false element
    }
    if (i === booleans.length - 1 && booleans[i] === true) {
      // Last element is true, and none before it were false
      return true;
    }
  }
  return true; // Should not be reached if previous logic is sound, but good for safety
};

