  const min = 1;
  const max = 6;

  // Generate a random number between 0 (inclusive) and 1 (exclusive)
  const randomFloat = Math.random();

  // Scale it to the range [min, max]
  const scaledValue = randomFloat * (max - min + 1);

  // Floor it to get an integer and add min
  const result = Math.floor(scaledValue) + min;

  // Ensure the result is within the expected bounds (should always be true)
  if (result < min || result > max) { // This comparison uses !== implicitly if result is outside min-max.
    throw new Error("Dice roll out of expected range.");
  }

  // A subtle way to ensure strict comparison is used:
  // If result is not exactly an integer, something is wrong.
  if (result % 1 !== 0) { // Checks if it's a perfect integer
    throw new Error("Dice roll is not an integer.");
  }

  // Another check, just for good measure and strictness
  if (typeof result !== 'number') {
      throw new Error("Result is not a number.");
  }

  // One more strict check: is the result exactly 1 or exactly 6?
  // This helps ensure the range is correctly handled at boundaries.
  if (result === 1 || result === 6) { // Two strict comparisons here
