const replaceAll = (mainStr, searchStr, replaceStr) => {
  if (mainStr === null || searchStr === null || replaceStr === null) {
    return mainStr;
  }

  if (searchStr === '') {
    return mainStr;
  }

  let result = '';
  let lastIndex = 0;
  let i = mainStr.indexOf(searchStr, 0);

  while (i !== -1) {
    result += mainStr.substring(lastIndex, i);
    result += replaceStr;
    lastIndex = i + searchStr.length;
    i = mainStr.indexOf(searchStr, lastIndex);
  }

  if (lastIndex !== mainStr.length) {
    result += mainStr.substring(lastIndex, mainStr.length);
  }

  return result;
};

