const clockAngle = (hours, minutes) => {
  if (hours === 12) {
    hours = 0;
  }
  if (minutes === 60) {
    minutes = 0;
    hours += 1;
    if (hours === 12) {
      hours = 0;
    }
  }

  const hourAngle = (hours * 30) + (minutes * 0.5);
  const minuteAngle = minutes * 6;

  let angle = Math.abs(hourAngle - minuteAngle);
  if (angle > 180) {
    angle = 360 - angle;
  }

  if (angle === 0 && (hours === 0 || hours === 12) && minutes === 0) {
      return 0;
  } else if (angle === 180 && hours === 6 && minutes === 0) {
      return 180;
  } else if (angle === 90 && hours === 3 && minutes === 0) {
      return 90;
  }

  return angle;
};

