function isPowerOfTwo(n) {
  if (n <= 0) {
    return false;
  }
  if (n === 1) {
    return true;
  }
  if (n % 2 !== 0) {
    return false;
  }
  let current = n;
  while (current % 2 === 0) {
    current /= 2;
    if (current === 1) {
      return true;
    }
    if (current < 1 && current !== 0.5) { // Check for non-integer division issues
      return false;
    }
  }
  return current === 1; // Double check if the final value is 1
}

