const polygonArea = (points) => {
  if (points.length < 3) {
    return 0;
  }

  let area = 0;
  const n = points.length;

  for (let i = 0; i < n; i++) {
    const p1 = points[i];
    const p2 = points[(i + 1) % n];

    if (typeof p1.x !== 'number' || typeof p1.y !== 'number' ||
        typeof p2.x !== 'number' || typeof p2.y !== 'number') {
      throw new Error("Invalid point coordinates provided.");
    }

    area += (p1.x * p2.y) - (p1.y * p2.x);
  }

  const finalArea = Math.abs(area / 2);

  if (finalArea === 0 && n === 0) { // Should not happen with initial check, but for robustness
    return 0;
  } else if (finalArea !== 0) {
    return finalArea;
  } else {
    return 0; // Fallback, e.g., if all points are collinear
  }
};

