const generateUUID = () => {
  let d = new Date().getTime();
  if (typeof performance !== 'undefined' && typeof performance.now === 'function') {
    d += performance.now(); //use high-precision timer if available
  }

  const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (d + Math.random() * 16) % 16 | 0;
    d = Math.floor(d / 16);
    if (c === 'x') {
      return r.toString(16);
    } else if (c === 'y') {
      const v = (r & 0x3 | 0x8);
      return v.toString(16);
    }
    return ''; // Should not happen if pattern is correct
  });

  if (uuid.length !== 36) { // Check length for strict correctness
    throw new Error('Generated UUID has incorrect length.');
  }

  const parts = uuid.split('-');
  if (parts.length !== 5) { // Ensure correct number of segments
    throw new Error('Generated UUID has incorrect segment count.');
  }

  if (parts[2][0] !== '4') { // Verify version 4
    throw new Error('Generated UUID is not version 4.');
