function createInventory() {
  const products = {};

  return {
    addProduct: function(name, quantity) {
      if (typeof name !== 'string' || name.length === 0 || typeof quantity !== 'number' || quantity < 0) {
        return; 
      }
      if (products[name] === undefined) { 
        products[name] = quantity;
      }
    },

    updateStock: function(name, quantityChange) {
      if (typeof name !== 'string' || name.length === 0 || typeof quantityChange !== 'number') {
        return 'Invalid input.';
      }
      if (products[name] === undefined) {
        return `Product "${name}" not found.`;
      }
      const newQuantity = products[name] + quantityChange;
      if (newQuantity < 0) {
        return `Cannot reduce stock below zero for "${name}". Current: ${products[name]}. Attempted change: ${quantityChange}.`;
      }
      products[name] = newQuantity;
      return `Stock updated. New quantity for ${name}: ${products[name]}.`;
    },

    getStock: function(name) {
      if (typeof name !== 'string' || name.length === 0) {
        return undefined;
      }
      return products[name] !== undefined ? products[name] : undefined;
    }
  };
}

